import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export class BookStorage {
  constructor(filePath = process.env.BOOK_STORAGE_PATH || path.join(process.cwd(), 'books.json')) {
    this.filePath = filePath;
    this._ensureFile();
  }

  _ensureFile() {
    try {
      const dir = path.dirname(this.filePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      if (!fs.existsSync(this.filePath)) {
        fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
      }
    } catch (err) {
      console.error(`Error ensuring storage file at ${this.filePath}:`, err);
    }
  }

  getBooks() {
    try {
      if (!fs.existsSync(this.filePath)) {
        this._ensureFile();
      }
      const data = fs.readFileSync(this.filePath, 'utf8');
      const parsed = JSON.parse(data);
      return Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      console.error(`Error reading books from ${this.filePath}:`, err);
      return [];
    }
  }

  saveBooks(books) {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const tempFile = `${this.filePath}.tmp.${Date.now()}`;
    const json = JSON.stringify(books, null, 2);
    fs.writeFileSync(tempFile, json, 'utf8');
    fs.renameSync(tempFile, this.filePath);
  }

  getBookById(id) {
    const books = this.getBooks();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  addBook({ title, author, notes = '', status = 'reading' }) {
    if (!title || !title.trim()) {
      throw new Error('Title is required');
    }

    const books = this.getBooks();
    const isFinished = status === 'finished';
    const now = new Date().toISOString();

    const newBook = {
      id: crypto.randomUUID(),
      title: title.trim(),
      author: (author || '').trim(),
      notes: (notes || '').trim(),
      status: isFinished ? 'finished' : 'reading',
      createdAt: now,
      finishedAt: isFinished ? now : null,
    };

    books.unshift(newBook);
    this.saveBooks(books);
    return newBook;
  }

  markBookAsFinished(id) {
    const books = this.getBooks();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) {
      return null;
    }

    books[index] = {
      ...books[index],
      status: 'finished',
      finishedAt: books[index].finishedAt || new Date().toISOString(),
    };

    this.saveBooks(books);
    return books[index];
  }

  updateBookStatus(id, newStatus) {
    const books = this.getBooks();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) {
      return null;
    }

    const isFinished = newStatus === 'finished';
    books[index] = {
      ...books[index],
      status: isFinished ? 'finished' : 'reading',
      finishedAt: isFinished ? (books[index].finishedAt || new Date().toISOString()) : null,
    };

    this.saveBooks(books);
    return books[index];
  }

  deleteBook(id) {
    const books = this.getBooks();
    const filtered = books.filter((b) => String(b.id) !== String(id));
    if (filtered.length !== books.length) {
      this.saveBooks(filtered);
      return true;
    }
    return false;
  }
}

export const defaultStorage = new BookStorage();

