export function renderHomePage({ readingBooks = [], finishedBooks = [] }) {
  const readingCards = readingBooks.length === 0
    ? `<div class="empty-state">
        <p>📚 No books currently being read.</p>
        <p style="font-size: 0.85rem; margin-top: 0.35rem;">Add a book using the form above to get started!</p>
      </div>`
    : `<div class="book-list">
        ${readingBooks.map((book) => `
          <div class="book-item">
            <div>
              <h3 class="book-title">
                <a href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
              </h3>
              <p class="book-author">by ${escapeHtml(book.author || 'Unknown')}</p>
              ${book.notes ? `<div class="notes-preview">${escapeHtml(book.notes.slice(0, 100))}${book.notes.length > 100 ? '...' : ''}</div>` : ''}
            </div>
            <div class="book-actions">
              <form method="POST" action="/books/${escapeHtml(book.id)}/finish">
                <button type="submit" class="btn btn-success btn-sm">✓ Mark as Finished</button>
              </form>
              <a href="/books/${escapeHtml(book.id)}" class="btn btn-outline btn-sm">View Details & Notes →</a>
            </div>
          </div>
        `).join('')}
      </div>`;

  const finishedCards = finishedBooks.length === 0
    ? `<div class="empty-state">
        <p>🎉 No finished books yet.</p>
        <p style="font-size: 0.85rem; margin-top: 0.35rem;">When you finish reading a book, mark it finished to see it here.</p>
      </div>`
    : `<div class="book-list">
        ${finishedBooks.map((book) => `
          <div class="book-item">
            <div>
              <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 0.5rem;">
                <h3 class="book-title">
                  <a href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
                </h3>
                <span class="badge badge-finished">Finished</span>
              </div>
              <p class="book-author">by ${escapeHtml(book.author || 'Unknown')}</p>
              ${book.notes ? `<div class="notes-preview">${escapeHtml(book.notes.slice(0, 100))}${book.notes.length > 100 ? '...' : ''}</div>` : ''}
            </div>
            <div class="book-actions">
              <form method="POST" action="/books/${escapeHtml(book.id)}/status">
                <input type="hidden" name="status" value="reading">
                <button type="submit" class="btn btn-outline btn-sm" title="Move back to Currently Reading">← Move to Reading</button>
              </form>
              <a href="/books/${escapeHtml(book.id)}" class="btn btn-outline btn-sm">View Details & Notes →</a>
            </div>
          </div>
        `).join('')}
      </div>`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Reading Tracker</title>
  <style>${baseStyles}</style>
</head>
<body>
  <div class="container">
    <header class="app-header">
      <h1>📖 Reading Tracker</h1>
      <p>Keep track of what you're reading and what you've finished.</p>
      <div class="stats-bar">
        <span class="stats-item">Currently Reading: <strong>${readingBooks.length}</strong></span>
        <span>•</span>
        <span class="stats-item">Finished: <strong>${finishedBooks.length}</strong></span>
      </div>
    </header>

    <section class="card" aria-label="Add a book">
      <h2>➕ Add a Book</h2>
      <form method="POST" action="/books" id="addBookForm">
        <div class="form-grid">
          <div class="form-group">
            <label for="title">Title *</label>
            <input type="text" id="title" name="title" required placeholder="e.g. Project Hail Mary">
          </div>
          <div class="form-group">
            <label for="author">Author *</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Andy Weir">
          </div>
          <div class="form-group full-width">
            <label for="status">Reading Status</label>
            <select id="status" name="status">
              <option value="reading" selected>Currently Reading</option>
              <option value="finished">Finished</option>
            </select>
          </div>
          <div class="form-group full-width">
            <label for="notes">My Notes & Thoughts</label>
            <textarea id="notes" name="notes" placeholder="Reflections, quotes, favorite chapters, or why you started reading..."></textarea>
          </div>
          <div class="form-group full-width">
            <button type="submit" class="btn btn-primary">Add to Library</button>
          </div>
        </div>
      </form>
    </section>

    <div class="sections-grid">
      <section class="section-column" aria-label="Currently Reading">
        <h2>
          <span>Currently Reading</span>
          <span class="badge-count">${readingBooks.length}</span>
        </h2>
        ${readingCards}
      </section>

      <section class="section-column" aria-label="Finished Books">
        <h2>
          <span>Finished</span>
          <span class="badge-count">${finishedBooks.length}</span>
        </h2>
        ${finishedCards}
      </section>
    </div>
  </div>
</body>
</html>`;
}

export function renderBookDetailPage({ book, fullUrl = '' }) {
  const isFinished = book.status === 'finished';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(book.title)} by ${escapeHtml(book.author || 'Unknown')} - Reading Tracker</title>
  <meta property="og:title" content="${escapeHtml(book.title)} by ${escapeHtml(book.author || 'Unknown')}">
  <meta property="og:description" content="${escapeHtml(book.notes || 'Tracked in Reading Tracker')}">
  <style>${baseStyles}</style>
</head>
<body>
  <div class="container">
    <a href="/" class="back-link">← Back to reading list</a>

    <div class="share-banner">
      <span class="share-label">🔗 Share this book:</span>
      <div class="share-input-wrap">
        <input type="text" id="shareUrl" readonly value="${escapeHtml(fullUrl)}">
        <button type="button" class="btn btn-outline btn-sm" id="copyBtn" onclick="copyShareUrl()">Copy Link</button>
      </div>
    </div>

    <article class="card">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; flex-wrap: wrap;">
        <div>
          <h1 style="font-size: 2rem; font-weight: 800; line-height: 1.25; color: var(--text-main);">
            ${escapeHtml(book.title)}
          </h1>
          <p class="book-author" style="font-size: 1.15rem; margin-top: 0.35rem;">
            by ${escapeHtml(book.author || 'Unknown')}
          </p>
        </div>
        <div>
          ${isFinished
            ? '<span class="badge badge-finished" style="font-size: 0.95rem; padding: 0.4rem 0.9rem;">✓ Finished</span>'
            : '<span class="badge badge-reading" style="font-size: 0.95rem; padding: 0.4rem 0.9rem;">📖 Currently Reading</span>'
          }
        </div>
      </div>

      <div class="notes-box">
        <h3>My Notes</h3>
        ${book.notes && book.notes.trim()
          ? `<div class="notes-content">${escapeHtml(book.notes)}</div>`
          : `<p class="empty-notes">No notes added for this book yet.</p>`
        }
      </div>

      <div class="detail-actions">
        ${!isFinished ? `
          <form method="POST" action="/books/${escapeHtml(book.id)}/finish">
            <button type="submit" class="btn btn-success">✓ Mark as Finished</button>
          </form>
        ` : `
          <form method="POST" action="/books/${escapeHtml(book.id)}/status">
            <input type="hidden" name="status" value="reading">
            <button type="submit" class="btn btn-outline">← Move to Currently Reading</button>
          </form>
        `}

        <form method="POST" action="/books/${escapeHtml(book.id)}/delete" onsubmit="return confirm('Are you sure you want to delete this book?');">
          <button type="submit" class="btn btn-danger btn-sm">Delete</button>
        </form>
      </div>
    </article>
  </div>

  <div id="toast" class="toast">Link copied to clipboard!</div>

  <script>
    function copyShareUrl() {
      const input = document.getElementById('shareUrl');
      input.select();
      navigator.clipboard.writeText(input.value).then(() => {
        showToast('Link copied to clipboard!');
      }).catch(() => {
        document.execCommand('copy');
        showToast('Link copied to clipboard!');
      });
    }

    function showToast(msg) {
      const toast = document.getElementById('toast');
      toast.textContent = msg;
      toast.style.display = 'block';
      setTimeout(() => {
        toast.style.display = 'none';
      }, 2500);
    }

    // Update share url with window.location.href if fullUrl wasn't set or differs
    if (window.location && window.location.href) {
      const input = document.getElementById('shareUrl');
      if (input) {
        input.value = window.location.href;
      }
    }
