import express from 'express';
import { BookStorage, defaultStorage } from './storage.js';
import { renderHomePage, renderBookDetailPage, renderNotFoundPage } from './templates.js';

export function createApp(storage = defaultStorage) {
  const app = express();

  app.use(express.urlencoded({ extended: true }));
  app.use(express.json());

  // Helper to detect if client wants JSON
  function wantsJson(req) {
    const accept = req.headers.accept || '';
    return accept.includes('application/json') || req.path.startsWith('/api/');
  }

  // Home: View currently reading and finished books
  app.get('/', (req, res) => {
    const allBooks = storage.getBooks();
    const readingBooks = allBooks.filter((b) => b.status === 'reading');
    const finishedBooks = allBooks.filter((b) => b.status === 'finished');

    if (wantsJson(req)) {
      return res.json({
        reading: readingBooks,
        finished: finishedBooks,
        all: allBooks,
      });
    }

    const html = renderHomePage({ readingBooks, finishedBooks });
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  });

  // Direct single book view
  app.get('/books/:id', (req, res) => {
    const book = storage.getBookById(req.params.id);
    if (!book) {
      if (wantsJson(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.status(404).send(renderNotFoundPage());
    }

    if (wantsJson(req)) {
      return res.json(book);
    }

    const protocol = req.protocol;
    const host = req.get('host') || 'localhost:3000';
    const fullUrl = `${protocol}://${host}/books/${book.id}`;

    const html = renderBookDetailPage({ book, fullUrl });
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  });

  // Add a book from form or API
  app.post('/books', (req, res) => {
    const { title, author, notes, status } = req.body;

    if (!title || !title.trim()) {
      if (wantsJson(req)) {
        return res.status(400).json({ error: 'Title is required' });
      }
      return res.redirect('/');
    }

    const newBook = storage.addBook({
      title,
      author,
      notes,
      status: status === 'finished' ? 'finished' : 'reading',
    });

    if (wantsJson(req)) {
      return res.status(201).json(newBook);
    }

    res.redirect('/');
  });

  // Mark book as finished
  app.post('/books/:id/finish', (req, res) => {
    const updated = storage.markBookAsFinished(req.params.id);
    if (!updated) {
      if (wantsJson(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.status(404).send(renderNotFoundPage());
    }

    if (wantsJson(req)) {
      return res.json(updated);
    }

    const referrer = req.get('Referrer');
    if (referrer && referrer.includes(`/books/${req.params.id}`)) {
      return res.redirect(`/books/${req.params.id}`);
    }
    res.redirect('/');
  });

  // Update book status (e.g. move back to reading)
  app.post('/books/:id/status', (req, res) => {
    const targetStatus = req.body.status === 'reading' ? 'reading' : 'finished';
    const updated = storage.updateBookStatus(req.params.id, targetStatus);
    if (!updated) {
      if (wantsJson(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.status(404).send(renderNotFoundPage());
    }

    if (wantsJson(req)) {
      return res.json(updated);
    }

    const referrer = req.get('Referrer');
    if (referrer && referrer.includes(`/books/${req.params.id}`)) {
      return res.redirect(`/books/${req.params.id}`);
    }
    res.redirect('/');
  });

  // Delete a book
  app.post('/books/:id/delete', (req, res) => {
    const success = storage.deleteBook(req.params.id);
    if (!success) {
      if (wantsJson(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.status(404).send(renderNotFoundPage());
    }

    if (wantsJson(req)) {
      return res.json({ success: true });
    }

    res.redirect('/');
  });

  // Dedicated API routes
  app.get('/api/books', (req, res) => {
    const all = storage.getBooks();
    res.json(all);
  });

  app.get('/api/books/:id', (req, res) => {
    const book = storage.getBookById(req.params.id);
    if (!book) return res.status(404).json({ error: 'Book not found' });
    res.json(book);
  });

  app.post('/api/books', (req, res) => {
    const { title, author, notes, status } = req.body;
    if (!title || !title.trim()) {
      return res.status(400).json({ error: 'Title is required' });
    }
    const book = storage.addBook({ title, author, notes, status });
    res.status(201).json(book);
  });

  app.post('/api/books/:id/finish', (req, res) => {
    const updated = storage.markBookAsFinished(req.params.id);
    if (!updated) return res.status(404).json({ error: 'Book not found' });
    res.json(updated);
  });

  return app;
}

import { createApp } from './src/app.js';
import { defaultStorage } from './src/storage.js';

const app = createApp(defaultStorage);
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Reading Tracker running at http://localhost:${PORT}`);
});

