import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import http from 'node:http';
import { BookStorage } from '../src/storage.js';
import { createApp } from '../src/app.js';

describe('Book Tracking Application', () => {
  let tempDir;
  let testStoragePath;
  let storage;
  let app;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'book-test-'));
    testStoragePath = path.join(tempDir, 'books.json');
    storage = new BookStorage(testStoragePath);
    app = createApp(storage);

    await new Promise((resolve) => {
      server = http.createServer(app);
      server.listen(0, '127.0.0.1', () => {
        const addr = server.address();
        baseUrl = `http://127.0.0.1:${addr.port}`;
        resolve();
      });
    });
  });

  afterEach(async () => {
    await new Promise((resolve) => server.close(resolve));
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {
      // ignore
    }
  });

  describe('Storage persistence', () => {
    it('creates books.json file and saves books', () => {
      expect(fs.existsSync(testStoragePath)).toBe(true);
      const initial = JSON.parse(fs.readFileSync(testStoragePath, 'utf8'));
      expect(initial).toEqual([]);

      const book = storage.addBook({
        title: 'The Hobbit',
        author: 'J.R.R. Tolkien',
        notes: 'In a hole in the ground there lived a hobbit.',
      });

      expect(book.id).toBeDefined();
      expect(book.status).toBe('reading');

      // Verify written to disk
      const onDisk = JSON.parse(fs.readFileSync(testStoragePath, 'utf8'));
      expect(onDisk.length).toBe(1);
      expect(onDisk[0].title).toBe('The Hobbit');
    });

    it('persists data after application restart (reinstantiating storage from same JSON file)', () => {
      storage.addBook({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Fist my bump!',
      });

      // Simulate app restart by creating a brand new BookStorage instance pointing to testStoragePath
      const restartedStorage = new BookStorage(testStoragePath);
      const books = restartedStorage.getBooks();
      expect(books.length).toBe(1);
      expect(books[0].title).toBe('Project Hail Mary');
      expect(books[0].author).toBe('Andy Weir');
      expect(books[0].notes).toBe('Fist my bump!');
    });
  });

  describe('HTTP endpoints & User workflows', () => {
    it('shows empty currently reading and finished sections when opening home', async () => {
      const res = await fetch(`${baseUrl}/`);
      expect(res.status).toBe(200);
      const html = await res.text();
      expect(html).toContain('Currently Reading');
      expect(html).toContain('Finished');
      expect(html).toContain('No books currently being read');
      expect(html).toContain('No finished books yet');
    });

    it('adds a book from the form and displays it under currently reading', async () => {
      const formData = new URLSearchParams({
        title: 'Dune',
        author: 'Frank Herbert',
        notes: 'Fear is the mind-killer.',
        status: 'reading',
      });

      const addRes = await fetch(`${baseUrl}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData.toString(),
        redirect: 'manual',
      });

      // Redirects to / after form submission
      expect([302, 303]).toContain(addRes.status);

      // Home should now display Dune in Currently Reading
      const homeRes = await fetch(`${baseUrl}/`);
      const homeHtml = await homeRes.text();
      expect(homeHtml).toContain('Dune');
      expect(homeHtml).toContain('Frank Herbert');
      expect(homeHtml).toContain('Fear is the mind-killer');
    });

    it('allows clicking through to a book to see its title, author and notes', async () => {
      const book = storage.addBook({
        title: '1984',
        author: 'George Orwell',
        notes: 'Big Brother is watching you.',
      });

      const bookRes = await fetch(`${baseUrl}/books/${book.id}`);
      expect(bookRes.status).toBe(200);
      const bookHtml = await bookRes.text();

      expect(bookHtml).toContain('1984');
      expect(bookHtml).toContain('George Orwell');
      expect(bookHtml).toContain('Big Brother is watching you.');
      // Should show share link input
      expect(bookHtml).toContain(`/books/${book.id}`);
    });

    it('allows marking a book as finished and moves it to finished section', async () => {
      const book = storage.addBook({
        title: 'Atomic Habits',
        author: 'James Clear',
        notes: '1% better every day.',
      });

      expect(book.status).toBe('reading');

      // Submit finish form
      const finishRes = await fetch(`${baseUrl}/books/${book.id}/finish`, {
        method: 'POST',
        redirect: 'manual',
      });
      expect([302, 303]).toContain(finishRes.status);

      // Verify on disk and storage
      const updated = storage.getBookById(book.id);
      expect(updated.status).toBe('finished');

      // Home page should now show it in Finished section
      const homeRes = await fetch(`${baseUrl}/`);
      const homeHtml = await homeRes.text();
      expect(homeHtml).toContain('Atomic Habits');
      // The finished count should be 1
      expect(homeHtml).toContain('Finished: <strong>1</strong>');
    });

    it('supports direct shareable links to a single book', async () => {
      const book = storage.addBook({
        title: 'Clean Code',
        author: 'Robert C. Martin',
        notes: 'Even bad code can function. But it can bring a project to its knees.',
      });

      // Someone receives link:
      const shareUrl = `${baseUrl}/books/${book.id}`;
      const res = await fetch(shareUrl);
      expect(res.status).toBe(200);
      const html = await res.text();
      expect(html).toContain('Clean Code');
      expect(html).toContain('Robert C. Martin');
      expect(html).toContain('Even bad code can function');
      expect(html).toContain('Share this book:');
    });

    it('returns 404 for non-existent book', async () => {
      const res = await fetch(`${baseUrl}/books/non-existent-id`);
      expect(res.status).toBe(404);
      const html = await res.text();
      expect(html).toContain('Book Not Found');
    });

    it('supports JSON API operations', async () => {
      // Create via JSON API
      const createRes = await fetch(`${baseUrl}/api/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: 'The Pragmatic Programmer',
          author: 'Andy Hunt & Dave Thomas',
          notes: 'Care about your craft.',
          status: 'reading',
        }),
      });
      expect(createRes.status).toBe(201);
      const createdBook = await createRes.json();
      expect(createdBook.title).toBe('The Pragmatic Programmer');

      // Get via JSON API
      const getRes = await fetch(`${baseUrl}/api/books/${createdBook.id}`);
      expect(getRes.status).toBe(200);
      const fetchedBook = await getRes.json();
      expect(fetchedBook.notes).toBe('Care about your craft.');

      // Mark finished via API
      const finishRes = await fetch(`${baseUrl}/api/books/${createdBook.id}/finish`, {
        method: 'POST',
      });
      expect(finishRes.status).toBe(200);
      const finishedBook = await finishRes.json();
      expect(finishedBook.status).toBe('finished');
    });
  });
});

